export default function MenuCard({ item }) {
  return (
    <div className="card">
      <h3>{item.name}</h3>
      <p>₹{item.price}</p>

      <button className="btn btn-primary add-cart-btn">
        <span className="cart-icon">🛒</span>
        <span>Add to Cart</span>
      </button>
    </div>
  );
}
